const checkout = $json || {};
const body = checkout.body && typeof checkout.body === 'object' ? checkout.body : {};
const orderId = Number(body.order_id);
return {json:{checkout_status:Number(checkout.statusCode || 0),order_id:Number.isInteger(orderId) && orderId > 0 ? orderId : null,checkout_body:body,attempt:$('Load Executed Rollback').first().json,version: $('Read Back Active Version').first().json,health: $('Check Service Health').first().json}};
